window.AUTH=window.AUTH||{};window.AUTH["82-1766"]={"d":"82-1766","id":"1983/82-1766","n":"Securities Industry Association v. Board of Governors of the Federal Reserve System","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the respondents","date":"","url":"https://www.justice.gov/osg/media/224021/dl?inline","side":"res","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/securities-industry-association-et-al-petitioners-v-board-governors-federal-reserve-system","toa":false,"n":58}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep468/usrep468137/usrep468137.pdf","tr":false,"items":[{"t":"case","label":"Court in Investment Company Institute v. Camp","cite":"401 U.S. 617","y":1971,"id":"1970/61","sc":1,"op":8,"sum":"Petitioners in No. 61, an association of open-end investment companies and several individual such companies, attack (1) portions of the Comptroller of the Currency's Regulation 9, purporting to authorize banks to operate collective investment funds, as violative of the Glass-Steagall Banking Act of 1933 and (2) the Comptroller's approval given First National City Bank to operate a collective investment fund. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Board of Governors of the Federal Reserve System v. Investment Company Institute","cite":"450 U.S. 46","y":1981,"id":"1980/79-927","sc":1,"op":6,"sum":"The amendment to Regulation Y does not exceed the Board's statutory authority.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Jarecki v. G.D. Searle & Co.","cite":"367 U.S. 303","y":1961,"id":"1960/151","sc":1,"sum":"1. Development of new products is not \"discovery\" within the meaning of § 456 (a) (2) (B) of the Internal Revenue Code of 1939, as amended; and income resulting from the manufacture and sale of certain patented drugs, cameras, camera equipment and stereo products resulting from inventions is not included within the statutory definition of \"abnormal income,\" in § 456 (a), so as to qualify for Korean War excess …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United Housing Foundation, Inc. v. Forman","cite":"421 U.S. 837","y":1975,"id":"1974/74-157","sc":1,"op":1,"sum":"Respondents are 57 residents of Co-op City, a massive cooperative housing project in New York City, organized, financed, and constructed under the New York Private Housing Finance Law (Mitchell-Lama Act). They brought this action on behalf of all the apartment owners and derivatively on behalf of the housing corporation, alleging, inter alia, violations of the antifraud provisions of the Securities Act of 1933 and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Marine Bank v. Weaver","cite":"455 U.S. 551","y":1982,"id":"1981/80-1562","sc":1,"sum":"Neither the certificate of deposit nor the agreement in question is a security within the meaning of § 10(b).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Erlenbaugh v. United States","cite":"409 U.S. 239","y":1972,"id":"1972/71-839","sc":1,"sum":"Causing a publication to be carried by a facility of interstate commerce with an intent to facilitate the operation of an illegal gambling business is a violation of 18 U. S. C. § 1952. The exception for \"any newspaper or similar publication\" contained in 18 U. S. C. § 1953, which prohibits the interstate shipment of certain gambling paraphernalia, was not intended to be read into § 1952. Pp. 242-248. 452 F. 2d 967, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Board of Governors of the Federal Reserve System v. Agnew","cite":"329 U.S. 441","y":1947,"id":"scdb/1946-031","sc":1,"sum":"The partnership was \"primarily engaged\" in the underwriting and distribution of securities within the meaning of § 32 of the Act and its employees were disqualified from serving as directors of a member bank of the Federal Reserve System.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"John Nuveen & Co. v. Sanders","cite":"425 U.S. 929","y":1976,"url":"https://supreme.justia.com/cases/federal/us/425/929/","sc":1,"op":1,"by":{"0":""}},{"t":"case","label":"Sanders v. John Nuveen & Co.","cite":"463 F.2d 1075","url":"https://www.courtlistener.com/c/F.2d/463/1075/","by":{"0":""}},{"t":"case","label":"Zeller v. Bogue Electric Manufacturing Corp.","cite":"476 F.2d 795","url":"https://www.courtlistener.com/c/F.2d/476/795/","by":{"0":""}},{"t":"case","label":"C.N.S. Enterprises, Inc. v. G. & G. Enterprises, Inc.","cite":"508 F.2d 1354","url":"https://www.courtlistener.com/c/F.2d/508/1354/","by":{"0":""}},{"t":"case","label":"Third National Bank v. IMPAC, Ltd.","cite":"432 U.S. 312","y":1977,"id":"1976/76-674","sc":1,"op":1,"sum":"Title 12 U. S. C. § 91, which prohibits an \"attachment, injunction, or execution\" from being issued against a national bank or its property before final judgment in any state or local court, held, when read in context, merely to prevent prejudgment seizure of bank property by creditors and not to apply to a mortgagor-debtor's action seeking a preliminary injunction to protect its real property from wrongful …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Philbrook v. Glodgett","cite":"421 U.S. 707","y":1975,"id":"1974/73-1820","sc":1,"sum":"Under the Aid to Families with Dependent Children (AFDC) program of the Social Security Act (Act), the term \"dependent child\" was expanded to include children whose deprivation was caused by a parent's unemployment. Section 407 (b) (2) (C) (ii) of the Act, as amended in 1968, makes this expanded definition applicable only if a state plan under the AFDC program denies aid to a dependent child so defined \"with respect …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Consumer Product Safety Commission v. GTE Sylvania","cite":"447 U.S. 102","y":1980,"id":"1979/79-521","sc":1,"sum":"Section 6 (b) (1) governs the disclosure of records by the Commission pursuant to a request under the FOIA.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Price","cite":"361 U.S. 304","y":1960,"id":"1959/48","sc":1,"sum":"Under § 272 (a) (1) of the Internal Revenue Code of 1939, as amended, failure of the Commissioner of Internal Revenue to send to a taxpayer a 90-day notice of a deficiency in his income tax return does not bar an action by the United States to collect such deficiency and statutory interest thereon when the taxpayer had executed and filed, under § 272 (d), a waiver of the restrictions of § 272 (a) on the assessment …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"American Bank & Trust Co. v. Wallace","cite":"702 F.2d 93","y":1983,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/702/93/","by":{"0":""}},{"t":"case","label":"Williamson v. Tucker","cite":"645 F.2d 404","y":1981,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/645/404/","by":{"0":""}},{"t":"case","label":"National Bank of Commerce v. All American Assurance Co.","cite":"583 F.2d 1295","y":1978,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/583/1295/","by":{"0":""}},{"t":"case","label":"Emisco Industries, Inc. v. Pro's, Inc.","cite":"543 F.2d 38","y":1976,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/543/38/","by":{"0":""}},{"t":"case","label":"Zabriskie v. Lewis","cite":"507 F.2d 546","y":1974,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/507/546/","by":{"0":""}},{"t":"case","label":"McClure v. First National Bank","cite":"497 F.2d 490","y":1974,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/497/490/","by":{"0":""}},{"t":"case","label":"Bellah v. First National Bank","cite":"495 F.2d 1109","y":1974,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/495/1109/","by":{"0":""}},{"t":"case","label":"Lino v. City Investing Co.","cite":"487 F.2d 689","y":1973,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/487/689/","by":{"0":""}},{"t":"case","label":"Amfac Mortgage Corp. v. Arizona Mall of Tempe, Inc.","cite":"583 F.2d 426","y":1978,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/583/426/","by":{"0":""}},{"t":"case","label":"Great Western Bank & Trust v. Kotz","cite":"532 F.2d 1252","y":1976,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/532/1252/","op":1,"by":{"0":""}},{"t":"case","label":"United States v. Connecticut National Bank","cite":"418 U.S. 656","y":1974,"id":"1973/73-767","sc":1,"op":1,"sum":"The United States brought this civil antitrust action under § 7 of the Clayton Act challenging a proposed consolidation between the Connecticut National Bank (CNB) and the First New Haven National Bank (FNH), which are, respectively, the fourth and eighth largest commercial banks in Connecticut. The banks operate in contiguous areas of the State, CNB having headquarters in Bridgeport, with 51 offices there and in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"American Fletcher Mortgage Co. v. United States Steel Credit Corp.","cite":"635 F.2d 1247","y":1980,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/635/1247/","by":{"0":""}},{"t":"case","label":"Robbins v. First American Bank","cite":"514 F. Supp. 1183","y":1981,"court":"N.D. Ill.","url":"https://www.courtlistener.com/c/F.%20Supp./514/1183/","by":{"0":""}},{"t":"case","label":"SEC v. Ralston Purina Co.","cite":"346 U.S. 119","y":1953,"id":"scdb/1952-105","sc":1,"sum":"These transactions were not exempted under § 4 (1) of the Act as transactions \"not involving any public offering.\"","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Union Planters National Bank v. Commercial Credit Business Loans, Inc.","cite":"651 F.2d 1174","url":"https://www.courtlistener.com/c/F.2d/651/1174/","by":{"0":""}},{"t":"case","label":"United American Bank v. Gunter","cite":"620 F.2d 1108","y":1980,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/620/1108/","by":{"0":""}},{"t":"case","label":"Lehigh Valley Trust Co. v. Central National Bank","cite":"409 F.2d 989","y":1969,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/409/989/","by":{"0":""}},{"t":"case","label":"Baker, Watts & Co. v. Saxon","cite":"261 F. Supp. 247","y":1966,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./261/247/","by":{"0":""}},{"t":"case","label":"Port of New York Authority v. Baker, Watts & Co.","cite":"392 F.2d 497","y":1968,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/392/497/","by":{"0":""}},{"t":"case","label":"Unemployment Compensation Commission v. Aragon","cite":"329 U.S. 143","y":1946,"id":"scdb/1946-009","sc":1,"sum":"Companies engaged in catching and canning salmon in Alaska terminated their agreement with the union representing their employees at the end of the 1939 season. Prior to the beginning of the 1940 season, they opened negotiations in San Francisco with the same union for a new agreement. There ensued a controversy over wages which resulted in a failure to reach an agreement aaid a decision to conduct no operations …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"FEC v. Democratic Senatorial Campaign Committee","cite":"454 U.S. 27","y":1981,"id":"1981/80-939","sc":1,"op":2,"sum":"Section 441a(d)(3) does not expressly or by necessary implication foreclose the use of agency agreements, such as are at issue here, and the FEC thus acted within the authority vested in it by Congress when it determined to permit such agreements.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Ford Motor Credit Co. v. Milhollin","cite":"444 U.S. 555","y":1980,"id":"1979/78-1487","sc":1,"sum":"TILA does not mandate a general rule of disclosure for acceleration clauses.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Udall v. Tallman","cite":"380 U.S. 1","y":1965,"id":"1964/34","sc":1,"sum":"Since their promulgation, the Secretary of the Interior has consistently construed Executive Order No. 8979 and Public Land Order No. 487, relating to the disposition of public lands located in the Kenai National Moose Range in Alaska, not to bar the issuance of oil and gas leases. His interpretation has been made a repeated matter of public record, and a number of leases have been developed, at great expense, in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"SIA v. Board of Governors of the Federal Reserve System","cite":"716 F.2d 92","y":1983,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/716/92/","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 24","url":"https://www.law.cornell.edu/uscode/text/12/24","stext":{"head":"§24. Corporate powers of associations","paras":[[0,"Upon duly making and filing articles of association and an organization certificate a national banking association shall become, as from the date of the execution of its organization certificate, a body corporate, and as such, and in the name designated in the organization certificate, it shall have power—"],[0,"First. To adopt and use a corporate seal."],[0,"Second. To have succession from February 25, 1927, or from the date of its organization if organized after February 25, 1927, until such time as it be dissolved by the act of its shareholders owning two-thirds of its stock, or until its franchise becomes forfeited by reason of violation of law, or until terminated by either a general or a special Act of Congress or until its affairs be placed in the hands of a receiver and finally wound up by him."],[0,"Third. To make contracts."],[0,"Fourth. To sue and be sued, complain and defend, in any court of law and equity, as fully as natural persons."],[0,"Fifth. To elect or appoint directors, and by its board of directors to appoint a president, vice president, cashier, and other officers, define their duties, require bonds of them and fix the penalty thereof, dismiss such officers or any of them at pleasure, and appoint others to fill their places."],[0,"Sixth. To prescribe, by its board of directors, bylaws not inconsistent with law, regulating the manner in which its stock shall be transferred, its directors elected or appointed, its officers appointed, its property transferred, its general business conducted, and the privileges granted to it by law exercised and enjoyed."],[0,"Seventh. To exercise by its board of directors or duly authorized officers or agents, subject to law, all such incidental powers as shall be necessary to carry on the business of banking; by discounting and negotiating promissory notes, drafts, bills of exchange, and other evidences of debt; by receiving deposits; by buying and selling exchange, coin, and bullion; by loaning money on personal security; and by obtaining, issuing, and circulating notes according to the provisions of title 62 of the Revised Statutes. The business of dealing in securities and stock by the association shall be limited to purchasing and selling such securities and stock without recourse, solely upon the order, and for the account of, customers, and in no case for its own account, and the association shall not underwrite any issue of securities or stock; Provided, That the association may purchase for its own account investment securities under such limitations and restrictions as the Comptroller of the Currency may by regulation prescribe. In no event shall the total amount of the investment securities of any one obligor or maker, held by the association for its own account, exceed at any time 10 per centum of its capital stock actually paid in and unimpaired and 10 per centum of its unimpaired surplus fund, except that this limitation shall not require any association to dispose of any securities lawfully held by it on August 23, 1935. As used in this section the term \"investment securities\" shall mean marketable obligations, evidencing indebtedness of any person, copartnership, association, or corporation in the form of bonds, notes and/or debentures commonly known as investment securities under such further definition of the term \"investment securities\" as may by regulation be prescribed by the Comptroller of the Currency. Except as hereinafter provided or otherwise permitted by law, nothing herein contained shall authorize the purchase by the association for its own account of any shares of stock of any corporation. The limitations and restrictions herein contained as to dealing in, underwriting and purchasing for its own account, investment securities shall not apply to obligations of the United States, or general obligations of any State or of any political subdivision thereof, or obligations of the Washington Metropolitan Area Transit Authority which are guaranteed by the Secretary of Transportation under section 9 of the National Capital Transportation Act of 1969, or obligations issued under authority of the Federal Farm Loan Act, as amended, or issued by the thirteen banks for cooperatives or any of them or the Federal Home Loan Banks, or obligations which are insured by the Secretary of Housing and Urban Development under title XI of the National Housing Act [12 U.S.C. 1749aaa et seq.] or obligations which are insured by the Secretary of Housing and Urban Development (hereinafter in this sentence referred to as the \"Secretary\") pursuant to section 207 of the National Housing Act [12 U.S.C. 1713], if the debentures to be issued in payment of such insured obligations are guaranteed as to principal and interest by the United States, or obligations, participations, or other instruments of or issued by the Federal National Mortgage Association, or the Government National Mortgage Association, or mortgages, obligations or other securities which are or ever have been sold by the Federal Home Loan Mortgage Corporation pursuant to section 305 or section 306 of the Federal Home Loan Mortgage Corporation Act [12 U.S.C. 1454 or 1455], or obligations of the Federal Financing Bank or obligations of the Environmental Financing Authority, or obligations or other instruments or securities of the Student Loan Marketing Association, or such obligations of any local public agency (as defined in section 110(h) of the Housing Act of 1949 [42 U.S.C. 1460(h)]) as are secured by an agreement between the local public agency and the Secretary in which the local public agency agrees to borrow from said Secretary, and said Secretary agrees to lend to said local public agency, monies in an aggregate amount which (together with any other monies irrevocably committed to the payment of interest on such obligations) will suffice to pay, when due, the interest on and all installments (including the final installment) of the principal of such obligations, which monies under the terms of said agreement are required to be used for such payments, or such obligations of a public housing agency (as defined in the United States Housing Act of 1937, as amended [42 U.S.C. 1437 et seq.]) as are secured (1) by an agreement between the public housing agency and the Secretary in which the public housing agency agrees to borrow from the Secretary, and the Secretary agrees to lend to the public housing agency, prior to the maturity of such obligations, monies in an amount which (together with any other monies irrevocably committed to the payment of interest on such obligations) will suffice to pay the principal of such obligations with interest to maturity thereon, which monies under the terms of said agreement are required to be used for the purpose of paying the principal of and the interest on such obligations at their maturity, (2) by a pledge of annual contributions under an annual contributions contract between such public housing agency and the Secretary if such contract shall contain the covenant by the Secretary which is authorized by subsection (g) of section 6 of the United States Housing Act of 1937, as amended [42 U.S.C. 1437d(g)], and if the maximum sum and the maximum period specified in such contract pursuant to said subsection 6(g) [42 U.S.C. 1437d(g)] shall not be less than the annual amount and the period for payment which are requisite to provide for the payment when due of all installments of principal and interest on such obligations, or (3) by a pledge of both annual contributions under an annual contributions contract containing the covenant by the Secretary which is authorized by section 6(g) of the United States Housing Act of 1937 [42 U.S.C. 1437d(g)], and a loan under an agreement between the local public housing agency and the Secretary in which the public housing agency agrees to borrow from the Secretary, and the Secretary agrees to lend to the public housing agency, prior to the maturity of the obligations involved, moneys in an amount which (together with any other moneys irrevocably committed under the annual contributions contract to the payment of principal and interest on such obligations) will suffice to provide for the payment when due of all installments of principal and interest on such obligations, which moneys under the terms of the agreement are required to be used for the purpose of paying the principal and interest on such obligations at their maturity: Provided, That in carrying on the business commonly known as the safe-deposit business the association shall not invest in the capital stock of a corporation organized under the law of any State to conduct a safe-deposit business in an amount in excess of 15 per centum of the capital stock of the association actually paid in and unimpaired and 15 per centum of its unimpaired surplus. The limitations and restrictions herein contained as to dealing in and underwriting investment securities shall not apply to obligations issued by the International Bank for Reconstruction and Development, the European Bank for Reconstruction and Development, the Inter-American Development Bank 1 Bank for Economic Cooperation and Development in the Middle East and North Africa,,2 the North American Development Bank, the Asian Development Bank, the African Development Bank, the Inter-American Investment Corporation, or the International Finance Corporation,,2 or obligations issued by any State or political subdivision or any agency of a State or political subdivision for housing, university, or dormitory purposes, which are at the time eligible for purchase by a national bank for its own account, nor to bonds, notes and other obligations issued by the Tennessee Valley Authority or by the United States Postal Service: Provided, That no association shall hold obligations issued by any of said organizations as a result of underwriting, dealing, or purchasing for its own account (and for this purpose obligations as to which it is under commitment shall be deemed to be held by it) in a total amount exceeding at any one time 10 per centum of its capital stock actually paid in and unimpaired and 10 per centum of its unimpaired surplus fund. Notwithstanding any other provision in this paragraph, the association may purchase for its own account shares of stock issued by a corporation authorized to be created pursuant to title IX of the Housing and Urban Development Act of 1968 [42 U.S.C. 3931 et seq.], and may make investments in a partnership, limited partnership, or joint venture formed pursuant to section 907(a) or 907(c) of that Act [42 U.S.C. 3937(a) or 3937(c)]. Notwithstanding any other provision of this paragraph, the association may purchase for its own account shares of stock issued by any State housing corporation incorporated in the State in which the association is located and may make investments in loans and commitments for loans to any such corporation: Provided, That in no event shall the total amount of such stock held for its own account and such investments in loans and commitments made by the association exceed at any time 5 per centum of its capital stock actually paid in and unimpaired plus 5 per centum of its unimpaired surplus fund. Notwithstanding any other provision in this paragraph, the association may purchase for its own account shares of stock issued by a corporation organized solely for the purpose of making loans to farmers and ranchers for agricultural purposes, including the breeding, raising, fattening, or marketing of livestock. However, unless the association owns at least 80 per centum of the stock of such agricultural credit corporation the amount invested by the association at any one time in the stock of such corporation shall not exceed 20 per centum of the unimpaired capital and surplus of the association: Provided further, That notwithstanding any other provision of this paragraph, the association may purchase for its own account shares of stock of a bank insured by the Federal Deposit Insurance Corporation or a holding company which owns or controls such an insured bank if the stock of such bank or company is owned exclusively (except to the extent directors' qualifying shares are required by law) by depository institutions or depository institution holding companies (as defined in section 1813 of this title) and such bank or company and all subsidiaries thereof are engaged exclusively in providing services to or for other depository institutions, their holding companies, and the officers, directors, and employees of such institutions and companies, and in providing correspondent banking services at the request of other depository institutions or their holding companies (also referred to as a \"banker's bank\"), but in no event shall the total amount of such stock held by the association in any bank or holding company exceed at any time 10 per centum of the association's capital stock and paid in and unimpaired surplus and in no event shall the purchase of such stock result in an association's acquiring more than 5 per centum of any class of voting securities of such bank or company. The limitations and restrictions contained in this paragraph as to an association purchasing for its own account investment securities shall not apply to securities that (A) are offered and sold pursuant to section 4(5) of the Securities Act of 1933 (15 U.S.C. 77d(5)); 3 (B) are small business related securities (as defined in section 3(a)(53) of the Securities Exchange Act of 1934 [15 U.S.C. 78c(a)(53)]); or (C) are mortgage related securities (as that term is defined in section 3(a)(41) of the Securities Exchange Act of 1934 (15 U.S.C. 78c(a)(41)).4 The exception provided for the securities described in subparagraphs (A), (B), and (C) shall be subject to such regulations as the Comptroller of the Currency may prescribe, including regulations prescribing minimum size of the issue (at the time of initial distribution) or minimum aggregate sales prices, or both."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/24?type=usc&year=mostrecent&link-type=html"},"op":8,"head":"§24. Corporate powers of associations","tname":"Banks and Banking","by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 378","url":"https://www.law.cornell.edu/uscode/text/12/378","subs":["(a)(1)"],"stext":{"head":"§378. Dealers in securities engaging in banking business; individuals or associations engaging in banking business; examinations and reports; penalties","paras":[[0,"(a) After the expiration of one year after June 16, 1933, it shall be unlawful—"],[1,"(1) For any person, firm, corporation, association, business trust, or other similar organization, engaged in the business of issuing, underwriting, selling, or distributing, at wholesale or retail, or through syndicate participation, stocks, bonds, debentures, notes, or other securities, to engage at the same time to any extent whatever in the business of receiving deposits subject to check or to repayment upon presentation of a passbook, certificate of deposit, or other evidence of debt, or upon request of the depositor: Provided, That the provisions of this paragraph shall not prohibit national banks or State banks or trust companies (whether or not members of the Federal Reserve System) or other financial institutions or private bankers from dealing in, underwriting, purchasing, and selling investment securities, or issuing securities, to the extent permitted to national banking associations by the provisions of section 24 of this title: Provided further, That nothing in this paragraph shall be construed as affecting in any way such right as any bank, banking association, savings bank, trust company, or other banking institution, may otherwise possess to sell, without recourse or agreement to repurchase, obligations evidencing loans on real estate; or"],[1,"(2) For any person, firm, corporation, association, business trust, or other similar organization to engage, to any extent whatever with others than his or its officers, agents or employees, in the business of receiving deposits subject to check or to repayment upon presentation of a pass book, certificate of deposit, or other evidence of debt, or upon request of the depositor, unless such person, firm, corporation, association, business trust, or other similar organization (A) shall be incorporated under, and authorized to engage in such business by, the laws of the United States or of any State, Territory, or District, and subjected, by the laws of the United States, or of the State, Territory, or District wherein located, to examination and regulation, or (B) shall be permitted by the United States, any State, territory, or district to engage in such business and shall be subjected by the laws of the United States, or such State, territory, or district to examination and regulations or, (C) shall submit to periodic examination by the banking authority of the State, Territory, or District where such business is carried on and shall make and publish periodic reports of its condition, exhibiting in detail its resources and liabilities, such examination and reports to be made and published at the same times and in the same manner and under the same conditions as required by the law of such State, Territory, or District in the case of incorporated banking institutions engaged in such business in the same locality."],[0,"(b) Whoever shall willfully violate any of the provisions of this section shall upon conviction be fined not more than $5,000 or imprisoned not more than five years, or both, and any officer, director, employee, or agent of any person, firm, corporation, association, business trust, or other similar organization who knowingly participates in any such violation shall be punished by a like fine or imprisonment or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/378?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§378. Dealers in securities engaging in banking business; individuals or associations engaging in banking business; examinations and reports; penalties","tname":"Banks and Banking","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 77c","url":"https://www.law.cornell.edu/uscode/text/15/77c","subs":["(a)(3)"],"stext":{"head":"§77c. Classes of securities under this subchapter","paras":[[0,"(a) Exempted securities"],[0,"Except as hereinafter expressly provided, the provisions of this subchapter shall not apply to any of the following classes of securities:"],[1,"(1) Reserved."],[1,"(2) Any security issued or guaranteed by the United States or any territory thereof, or by the District of Columbia, or by any State of the United States, or by any political subdivision of a State or territory, or by any public instrumentality of one or more States or territories, or by any person controlled or supervised by and acting as an instrumentality of the Government of the United States pursuant to authority granted by the Congress of the United States; or any certificate of deposit for any of the foregoing; or any security issued or guaranteed by any bank; or any security issued by or representing an interest in or a direct obligation of a Federal Reserve bank; or any interest or participation in any common trust fund or similar fund that is excluded from the definition of the term \"investment company\" under section 3(c)(3) of the Investment Company Act of 1940 [15 U.S.C. 80a–3(c)(3)]; or any security which is an industrial development bond (as defined in section 103(c)(2) 1 of title 26) the interest on which is excludable from gross income under section 103(a)(1) 1 of title 26 if, by reason of the application of paragraph (4) or (6) of section 103(c) 1 of title 26 (determined as if paragraphs (4)(A), (5), and (7) were not included in such section 103(c)),1 paragraph (1) of such section 103(c) 1 does not apply to such security; or any interest or participation in a single trust fund, or in a collective trust fund maintained by a bank, or any security arising out of a contract issued by an insurance company, which interest, participation, or security is issued in connection with (A) a stock bonus, pension, or profit-sharing plan which meets the requirements for qualification under section 401 of title 26, (B) an annuity plan which meets the requirements for the deduction of the employer's contributions under section 404(a)(2) of title 26, (C) a governmental plan as defined in section 414(d) of title 26 which has been established by an employer for the exclusive benefit of its employees or their beneficiaries for the purpose of distributing to such employees or their beneficiaries the corpus and income of the funds accumulated under such plan, if under such plan it is impossible, prior to the satisfaction of all liabilities with respect to such employees and their beneficiaries, for any part of the corpus or income to be used for, or diverted to, purposes other than the exclusive benefit of such employees or their beneficiaries, or (D) a church plan, company, or account that is excluded from the definition of an investment company under section 3(c)(14) of the Investment Company Act of 1940 [15 U.S.C. 80a–3(c)(14)], other than any plan described in subparagraph (A), (B), (C), or (D) of this paragraph (i) the contributions under which are held in a single trust fund or in a separate account maintained by an insurance company for a single employer and under which an amount in excess of the employer's contribution is allocated to the purchase of securities (other than interests or participations in the trust or separate account itself) issued by the employer or any company directly or indirectly controlling, controlled by, or under common control with the employer, (ii) which covers employees some or all of whom are employees within the meaning of section 401(c)(1) of title 26 (other than a person participating in a church plan who is described in section 414(e)(3)(B) of title 26), or (iii) which is a plan funded by an annuity contract described in section 403(b) of title 26 (other than a retirement income account described in section 403(b)(9) of title 26, to the extent that the interest or participation in such single trust fund or collective trust fund is issued to a church, a convention or association of churches, or an organization described in section 414(e)(3)(A) of title 26 establishing or maintaining the retirement income account or to a trust established by any such entity in connection with the retirement income account). The Commission, by rules and regulations or order, shall exempt from the provisions of section 77e of this title any interest or participation issued in connection with a stock bonus, pension, profit-sharing, or annuity plan which covers employees some or all of whom are employees within the meaning of section 401(c)(1) of title 26, if and to the extent that the Commission determines this to be necessary or appropriate in the public interest and consistent with the protection of investors and the purposes fairly intended by the policy and provisions of this subchapter. For purposes of this paragraph, a security issued or guaranteed by a bank shall not include any interest or participation in any collective trust fund maintained by a bank; and the term \"bank\" means any national bank, or banking institution organized under the laws of any State, territory, or the District of Columbia, the business of which is substantially confined to banking and is supervised by the State or territorial banking commission or similar official; except that in the case of a common trust fund or similar fund, or a collective trust fund, the term \"bank\" has the same meaning as in the Investment Company Act of 1940 [15 U.S.C. 80a–1 et seq.];"],[1,"(3) Any note, draft, bill of exchange, or banker's acceptance which arises out of a current transaction or the proceeds of which have been or are to be used for current transactions, and which has a maturity at the time of issuance of not exceeding nine months, exclusive of days of grace, or any renewal thereof the maturity of which is likewise limited;"],[1,"(4) Any security issued by a person organized and operated exclusively for religious, educational, benevolent, fraternal, charitable, or reformatory purposes and not for pecuniary profit, and no part of the net earnings of which inures to the benefit of any person, private stockholder, or individual, or any security of a fund that is excluded from the definition of an investment company under section 3(c)(10)(B) of the Investment Company Act of 1940 [15 U.S.C. 80a–3(c)(10)(B)];"],[1,"(5) Any security issued (A) by a savings and loan association, building and loan association, cooperative bank, homestead association, or similar institution, which is supervised and examined by State or Federal authority having supervision over any such institution; or (B) by (i) a farmer's cooperative organization exempt from tax under section 521 of title 26, (ii) a corporation described in section 501(c)(16) of title 26 and exempt from tax under section 501(a) of title 26, or (iii) a corporation described in section 501(c)(2) of title 26 which is exempt from tax under section 501(a) of title 26 and is organized for the exclusive purpose of holding title to property, collecting income therefrom, and turning over the entire amount thereof, less expenses, to an organization or corporation described in clause (i) or (ii);"],[1,"(6) Any interest in a railroad equipment trust. For purposes of this paragraph \"interest in a railroad equipment trust\" means any interest in an equipment trust, lease, conditional sales contract, or other similar arrangement entered into, issued, assumed, guaranteed by, or for the benefit of, a common carrier to finance the acquisition of rolling stock, including motive power;"],[1,"(7) Certificates issued by a receiver or by a trustee or debtor in possession in a case under title 11, with the approval of the court;"],[1,"(8) Any insurance or endowment policy or annuity contract or optional annuity contract, issued by a corporation subject to the supervision of the insurance commissioner, bank commissioner, or any agency or officer performing like functions, of any State or Territory of the United States or the District of Columbia;"],[1,"(9) Except with respect to a security exchanged in a case under title 11, any security exchanged by the issuer with its existing security holders exclusively where no commission or other remuneration is paid or given directly or indirectly for soliciting such exchange;"],[1,"(10) Except with respect to a security exchanged in a case under title 11, any security which is issued in exchange for one or more bona fide outstanding securities, claims or property interests, or partly in such exchange and partly for cash, where the terms and conditions of such issuance and exchange are approved, after a hearing upon the fairness of such terms and conditions at which all persons to whom it is proposed to issue securities in such exchange shall have the right to appear, by any court, or by any official or agency of the United States, or by any State or Territorial banking or insurance commission or other governmental authority expressly authorized by law to grant such approval;"],[1,"(11) Any security which is a part of an issue offered and sold only to persons resident within a single State or Territory, where the issuer of such security is a person resident and doing business within or, if a corporation, incorporated by and doing business within, such State or Territory."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77c?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§77c. Classes of securities under this subchapter","tname":"Commerce and Trade","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 78c","url":"https://www.law.cornell.edu/uscode/text/15/78c","subs":["(a)(10)"],"stext":{"head":"§78c. Definitions and application","paras":[[0,"(a) Definitions"],[0,"When used in this chapter, unless the context otherwise requires—"],[1,"(1) The term \"exchange\" means any organization, association, or group of persons, whether incorporated or unincorporated, which constitutes, maintains, or provides a market place or facilities for bringing together purchasers and sellers of securities or for otherwise performing with respect to securities the functions commonly performed by a stock exchange as that term is generally understood, and includes the market place and the market facilities maintained by such exchange."],[1,"(2) The term \"facility\" when used with respect to an exchange includes its premises, tangible or intangible property whether on the premises or not, any right to the use of such premises or property or any service thereof for the purpose of effecting or reporting a transaction on an exchange (including, among other things, any system of communication to or from the exchange, by ticker or otherwise, maintained by or with the consent of the exchange), and any right of the exchange to the use of any property or service."],[1,"(3)(A) The term \"member\" when used with respect to a national securities exchange means (i) any natural person permitted to effect transactions on the floor of the exchange without the services of another person acting as broker, (ii) any registered broker or dealer with which such a natural person is associated, (iii) any registered broker or dealer permitted to designate as a representative such a natural person, and (iv) any other registered broker or dealer which agrees to be regulated by such exchange and with respect to which the exchange undertakes to enforce compliance with the provisions of this chapter, the rules and regulations thereunder, and its own rules. For purposes of sections 78f(b)(1), 78f(b)(4), 78f(b)(6), 78f(b)(7), 78f(d), 78q(d), 78s(d), 78s(e), 78s(g), 78s(h), and 78u of this title, the term \"member\" when used with respect to a national securities exchange also means, to the extent of the rules of the exchange specified by the Commission, any person required by the Commission to comply with such rules pursuant to section 78f(f) of this title."],[1,"(B) The term \"member\" when used with respect to a registered securities association means any broker or dealer who agrees to be regulated by such association and with respect to whom the association undertakes to enforce compliance with the provisions of this chapter, the rules and regulations thereunder, and its own rules."],[1,"(4) Broker.—"],[2,"(A) In general.—The term \"broker\" means any person engaged in the business of effecting transactions in securities for the account of others."],[2,"(B) Exception for certain bank activities.—A bank shall not be considered to be a broker because the bank engages in any one or more of the following activities under the conditions described:"],[3,"(i) Third party brokerage arrangements.—The bank enters into a contractual or other written arrangement with a broker or dealer registered under this chapter under which the broker or dealer offers brokerage services on or off the premises of the bank if—"],[4,"(I) such broker or dealer is clearly identified as the person performing the brokerage services;"],[4,"(II) the broker or dealer performs brokerage services in an area that is clearly marked and, to the extent practicable, physically separate from the routine deposit-taking activities of the bank;"],[4,"(III) any materials used by the bank to advertise or promote generally the availability of brokerage services under the arrangement clearly indicate that the brokerage services are being provided by the broker or dealer and not by the bank;"],[4,"(IV) any materials used by the bank to advertise or promote generally the availability of brokerage services under the arrangement are in compliance with the Federal securities laws before distribution;"],[4,"(V) bank employees (other than associated persons of a broker or dealer who are qualified pursuant to the rules of a self-regulatory organization) perform only clerical or ministerial functions in connection with brokerage transactions including scheduling appointments with the associated persons of a broker or dealer, except that bank employees may forward customer funds or securities and may describe in general terms the types of investment vehicles available from the bank and the broker or dealer under the arrangement;"],[4,"(VI) bank employees do not receive incentive compensation for any brokerage transaction unless such employees are associated persons of a broker or dealer and are qualified pursuant to the rules of a self-regulatory organization, except that the bank employees may receive compensation for the referral of any customer if the compensation is a nominal one-time cash fee of a fixed dollar amount and the payment of the fee is not contingent on whether the referral results in a transaction;"],[4,"(VII) such services are provided by the broker or dealer on a basis in which all customers that receive any services are fully disclosed to the broker or dealer;"],[4,"(VIII) the bank does not carry a securities account of the customer except as permitted under clause (ii) or (viii) of this subparagraph; and"],[4,"(IX) the bank, broker, or dealer informs each customer that the brokerage services are provided by the broker or dealer and not by the bank and that the securities are not deposits or other obligations of the bank, are not guaranteed by the bank, and are not insured by the Federal Deposit Insurance Corporation."],[3,"(ii) Trust activities.—The bank effects transactions in a trustee capacity, or effects transactions in a fiduciary capacity in its trust department or other department that is regularly examined by bank examiners for compliance with fiduciary principles and standards, and—"],[4,"(I) is chiefly compensated for such transactions, consistent with fiduciary principles and standards, on the basis of an administration or annual fee (payable on a monthly, quarterly, or other basis), a percentage of assets under management, or a flat or capped per order processing fee equal to not more than the cost incurred by the bank in connection with executing securities transactions for trustee and fiduciary customers, or any combination of such fees; and"],[4,"(II) does not publicly solicit brokerage business, other than by advertising that it effects transactions in securities in conjunction with advertising its other trust activities."],[3,"(iii) Permissible securities transactions.—The bank effects transactions in—"],[4,"(I) commercial paper, bankers acceptances, or commercial bills;"],[4,"(II) exempted securities;"],[4,"(III) qualified Canadian government obligations as defined in section 24 of title 12, in conformity with section 78o–5 of this title and the rules and regulations thereunder, or obligations of the North American Development Bank; or"],[4,"(IV) any standardized, credit enhanced debt security issued by a foreign government pursuant to the March 1989 plan of then Secretary of the Treasury Brady, used by such foreign government to retire outstanding commercial bank loans."],[3,"(iv) Certain stock purchase plans.—"],[4,"(I) Employee benefit plans.—The bank effects transactions, as part of its transfer agency activities, in the securities of an issuer as part of any pension, retirement, profit-sharing, bonus, thrift, savings, incentive, or other similar benefit plan for the employees of that issuer or its affiliates (as defined in section 1841 of title 12), if the bank does not solicit transactions or provide investment advice with respect to the purchase or sale of securities in connection with the plan."],[4,"(II) Dividend reinvestment plans.—The bank effects transactions, as part of its transfer agency activities, in the securities of an issuer as part of that issuer's dividend reinvestment plan, if—"],[5,"(aa) the bank does not solicit transactions or provide investment advice with respect to the purchase or sale of securities in connection with the plan; and"],[5,"(bb) the bank does not net shareholders' buy and sell orders, other than for programs for odd-lot holders or plans registered with the Commission."],[4,"(III) Issuer plans.—The bank effects transactions, as part of its transfer agency activities, in the securities of an issuer as part of a plan or program for the purchase or sale of that issuer's shares, if—"],[5,"(aa) the bank does not solicit transactions or provide investment advice with respect to the purchase or sale of securities in connection with the plan or program; and"],[5,"(bb) the bank does not net shareholders' buy and sell orders, other than for programs for odd-lot holders or plans registered with the Commission."],[4,"(IV) Permissible delivery of materials.—The exception to being considered a broker for a bank engaged in activities described in subclauses (I), (II), and (III) will not be affected by delivery of written or electronic plan materials by a bank to employees of the issuer, shareholders of the issuer, or members of affinity groups of the issuer, so long as such materials are—"],[5,"(aa) comparable in scope or nature to that permitted by the Commission as of November 12, 1999; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78c?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§78c. Definitions and application","tname":"Commerce and Trade","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 78o","url":"https://www.law.cornell.edu/uscode/text/15/78o","subs":["(a)(1)"],"by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 77b","url":"https://www.law.cornell.edu/uscode/text/15/77b","subs":["(1)"],"stext":{"head":"§77b. Definitions; promotion of efficiency, competition, and capital formation","paras":[[0,"(a) Definitions"],[0,"When used in this subchapter, unless the context otherwise requires—"],[1,"(1) The term \"security\" means any note, stock, treasury stock, security future, security-based swap, bond, debenture, evidence of indebtedness, certificate of interest or participation in any profit-sharing agreement, collateral-trust certificate, preorganization certificate or subscription, transferable share, investment contract, voting-trust certificate, certificate of deposit for a security, fractional undivided interest in oil, gas, or other mineral rights, any put, call, straddle, option, or privilege on any security, certificate of deposit, or group or index of securities (including any interest therein or based on the value thereof), or any put, call, straddle, option, or privilege entered into on a national securities exchange relating to foreign currency, or, in general, any interest or instrument commonly known as a \"security\", or any certificate of interest or participation in, temporary or interim certificate for, receipt for, guarantee of, or warrant or right to subscribe to or purchase, any of the foregoing."],[1,"(2) The term \"person\" means an individual, a corporation, a partnership, an association, a joint-stock company, a trust, any unincorporated organization, or a government or political subdivision thereof. As used in this paragraph the term \"trust\" shall include only a trust where the interest or interests of the beneficiary or beneficiaries are evidenced by a security."],[1,"(3) The term \"sale\" or \"sell\" shall include every contract of sale or disposition of a security or interest in a security, for value. The term \"offer to sell\", \"offer for sale\", or \"offer\" shall include every attempt or offer to dispose of, or solicitation of an offer to buy, a security or interest in a security, for value. The terms defined in this paragraph and the term \"offer to buy\" as used in subsection (c) of section 77e of this title shall not include preliminary negotiations or agreements between an issuer (or any person directly or indirectly controlling or controlled by an issuer, or under direct or indirect common control with an issuer) and any underwriter or among underwriters who are or are to be in privity of contract with an issuer (or any person directly or indirectly controlling or controlled by an issuer, or under direct or indirect common control with an issuer). Any security given or delivered with, or as a bonus on account of, any purchase of securities or any other thing, shall be conclusively presumed to constitute a part of the subject of such purchase and to have been offered and sold for value. The issue or transfer of a right or privilege, when originally issued or transferred with a security, giving the holder of such security the right to convert such security into another security of the same issuer or of another person, or giving a right to subscribe to another security of the same issuer or of another person, which right cannot be exercised until some future date, shall not be deemed to be an offer or sale of such other security; but the issue or transfer of such other security upon the exercise of such right of conversion or subscription shall be deemed a sale of such other security. Any offer or sale of a security futures product by or on behalf of the issuer of the securities underlying the security futures product, an affiliate of the issuer, or an underwriter, shall constitute a contract for sale of, sale of, offer for sale, or offer to sell the underlying securities. Any offer or sale of a security-based swap by or on behalf of the issuer of the securities upon which such security-based swap is based or is referenced, an affiliate of the issuer, or an underwriter, shall constitute a contract for sale of, sale of, offer for sale, or offer to sell such securities. The publication or distribution by a broker or dealer of a research report about an emerging growth company that is the subject of a proposed public offering of the common equity securities of such emerging growth company pursuant to a registration statement that the issuer proposes to file, or has filed, or that is effective shall be deemed for purposes of paragraph (10) of this subsection and section 77e(c) of this title not to constitute an offer for sale or offer to sell a security, even if the broker or dealer is participating or will participate in the registered offering of the securities of the issuer. As used in this paragraph, the term \"research report\" means a written, electronic, or oral communication that includes information, opinions, or recommendations with respect to securities of an issuer or an analysis of a security or an issuer, whether or not it provides information reasonably sufficient upon which to base an investment decision."],[1,"(4) The term \"issuer\" means every person who issues or proposes to issue any security; except that with respect to certificates of deposit, voting-trust certificates, or collateral-trust certificates, or with respect to certificates of interest or shares in an unincorporated investment trust not having a board of directors (or persons performing similar functions) or of the fixed, restricted management, or unit type, the term \"issuer\" means the person or persons performing the acts and assuming the duties of depositor or manager pursuant to the provisions of the trust or other agreement or instrument under which such securities are issued; except that in the case of an unincorporated association which provides by its articles for limited liability of any or all of its members, or in the case of a trust, committee, or other legal entity, the trustees or members thereof shall not be individually liable as issuers of any security issued by the association, trust, committee, or other legal entity; except that with respect to equipment-trust certificates or like securities, the term \"issuer\" means the person by whom the equipment or property is or is to be used; and except that with respect to fractional undivided interests in oil, gas, or other mineral rights, the term \"issuer\" means the owner of any such right or of any interest in such right (whether whole or fractional) who creates fractional interests therein for the purpose of public offering."],[1,"(5) The term \"Commission\" means the Securities and Exchange Commission."],[1,"(6) The term \"Territory\" means Puerto Rico, the Virgin Islands, and the insular possessions of the United States."],[1,"(7) The term \"interstate commerce\" means trade or commerce in securities or any transportation or communication relating thereto among the several States or between the District of Columbia or any Territory of the United States and any State or other Territory, or between any foreign country and any State, Territory, or the District of Columbia, or within the District of Columbia."],[1,"(8) The term \"registration statement\" means the statement provided for in section 77f of this title, and includes any amendment thereto and any report, document, or memorandum filed as part of such statement or incorporated therein by reference."],[1,"(9) The term \"write\" or \"written\" shall include printed, lithographed, or any means of graphic communication."],[1,"(10) The term \"prospectus\" means any prospectus, notice, circular, advertisement, letter, or communication, written or by radio or television, which offers any security for sale or confirms the sale of any security; except that (a) a communication sent or given after the effective date of the registration statement (other than a prospectus permitted under subsection (b) of section 77j of this title) shall not be deemed a prospectus if it is proved that prior to or at the same time with such communication a written prospectus meeting the requirements of subsection (a) of section 77j of this title at the time of 1 such communication was sent or given to the person to whom the communication was made, and (b) a notice, circular, advertisement, letter, or communication in respect of a security shall not be deemed to be a prospectus if it states from whom a written prospectus meeting the requirements of section 77j of this title may be obtained and, in addition, does no more than identify the security, state the price thereof, state by whom orders will be executed, and contain such other information as the Commission, by rules or regulations deemed necessary or appropriate in the public interest and for the protection of investors, and subject to such terms and conditions as may be prescribed therein, may permit."],[1,"(11) The term \"underwriter\" means any person who has purchased from an issuer with a view to, or offers or sells for an issuer in connection with, the distribution of any security, or participates or has a direct or indirect participation in any such undertaking, or participates or has a participation in the direct or indirect underwriting of any such undertaking; but such term shall not include a person whose interest is limited to a commission from an underwriter or dealer not in excess of the usual and customary distributors' or sellers' commission. As used in this paragraph the term \"issuer\" shall include, in addition to an issuer, any person directly or indirectly controlling or controlled by the issuer, or any person under direct or indirect common control with the issuer."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77b?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§77b. Definitions; promotion of efficiency, competition, and capital formation","tname":"Commerce and Trade","by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 1901","url":"https://www.law.cornell.edu/uscode/text/12/1901","by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 335","url":"https://www.law.cornell.edu/uscode/text/12/335","stext":{"head":"§335. Dealing in investment securities; limitations and conditions","paras":[[0,"State member banks shall be subject to the same limitations and conditions with respect to the purchasing, selling, underwriting, and holding of investment securities and stock as are applicable in the case of national banks under paragraph \"Seventh\" of section 24 of this title. This section shall not apply to any interest held by a State member bank in accordance with section 24a of this title and subject to the same conditions and limitations provided in such section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/335?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§335. Dealing in investment securities; limitations and conditions","tname":"Banks and Banking","by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 78","url":"https://www.law.cornell.edu/uscode/text/12/78","by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 377","url":"https://www.law.cornell.edu/uscode/text/12/377","op":1,"tname":"Banks and Banking","by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 84","url":"https://www.law.cornell.edu/uscode/text/12/84","stext":{"head":"§84. Lending limits","paras":[[0,"(a) Total loans and extensions of credit"],[0,"(1) The total loans and extensions of credit by a national banking association to a person outstanding at one time and not fully secured, as determined in a manner consistent with paragraph (2) of this subsection, by collateral having a market value at least equal to the amount of the loan or extension of credit shall not exceed 15 per centum of the unimpaired capital and unimpaired surplus of the association."],[0,"(2) The total loans and extensions of credit by a national banking association to a person outstanding at one time and fully secured by readily marketable collateral having a market value, as determined by reliable and continuously available price quotations, at least equal to the amount of the funds outstanding shall not exceed 10 per centum of the unimpaired capital and unimpaired surplus of the association. This limitation shall be separate from and in addition to the limitation contained in paragraph (1) of this subsection."],[0,"(b) Definitions"],[0,"For the purposes of this section—"],[1,"(1) the term \"loans and extensions of credit\" shall include—"],[2,"(A) all direct or indirect advances of funds to a person made on the basis of any obligation of that person to repay the funds or repayable from specific property pledged by or on behalf of the person;"],[2,"(B) to the extent specified by the Comptroller of the Currency, any liability of a national banking association to advance funds to or on behalf of a person pursuant to a contractual commitment; and"],[2,"(C) any credit exposure to a person arising from a derivative transaction, repurchase agreement, reverse repurchase agreement, securities lending transaction, or securities borrowing transaction between the national banking association and the person;"],[1,"(2) the term \"person\" shall include an individual, sole proprietorship, partnership, joint venture, association, trust, estate, business trust, corporation, sovereign government or agency, instrumentality, or political subdivision thereof, or any similar entity or organization; and"],[1,"(3) the term \"derivative transaction\" includes any transaction that is a contract, agreement, swap, warrant, note, or option that is based, in whole or in part, on the value of, any interest in, or any quantitative measure or the occurrence of any event relating to, one or more commodities, securities, currencies, interest or other rates, indices, or other assets."],[0,"(c) Exceptions"],[0,"The limitations contained in subsection (a) shall be subject to the following exceptions:"],[1,"(1) Loans or extensions of credit arising from the discount of commercial or business paper evidencing an obligation to the person negotiating it with recourse shall not be subject to any limitation based on capital and surplus."],[1,"(2) The purchase of bankers' acceptances of the kind described in section 372 of this title and issued by other banks shall not be subject to any limitation based on capital and surplus."],[1,"(3) Loans and extensions of credit secured by bills of lading, warehouse receipts, or similar documents transferring or securing title to readily marketable staples shall be subject to a limitation of 35 per centum of capital and surplus in addition to the general limitations if the market value of the staples securing each additional loan or extension of credit at all times equals or exceeds 115 per centum of the outstanding amount of such loan or extension of credit. The staples shall be fully covered by insurance whenever it is customary to insure such staples."],[1,"(4) Loans or extensions of credit secured by bonds, notes, certificates of indebtedness, or Treasury bills of the United States or by other such obligations fully guaranteed as to principal and interest by the United States shall not be subject to any limitation based on capital and surplus."],[1,"(5) Loans or extensions of credit to or secured by unconditional takeout commitments or guarantees of any department, agency, bureau, board, commission, or establishment of the United States or any corporation wholly owned directly or indirectly by the United States shall not be subject to any limitation based on capital and surplus."],[1,"(6) Loans or extensions of credit secured by a segregated deposit account in the lending bank shall not be subject to any limitation based on capital and surplus."],[1,"(7) Loans or extensions of credit to any financial institution or to any receiver, conservator, superintendent of banks, or other agent in charge of the business and property of such financial institution, when such loans or extensions of credit are approved by the Comptroller of the Currency, shall not be subject to any limitation based on capital and surplus."],[1,"(8)(A) Loans and extensions of credit arising from the discount of negotiable or nonnegotiable installment consumer paper which carries a full recourse endorsement or unconditional guarantee by the person transferring the paper shall be subject under this section to a maximum limitation equal to 25 per centum of such capital and surplus, notwithstanding the collateral requirements set forth in subsection (a)(2)."],[1,"(B) If the bank's files or the knowledge of its officers of the financial condition of each maker of such consumer paper is reasonably adequate, and an officer of the bank designated for that purpose by the board of directors of the bank certifies in writing that the bank is relying primarily upon the responsibility of each maker for payment of such loans or extensions of credit and not upon any full or partial recourse endorsement or guarantee by the transferor, the limitations of this section as to the loans or extensions of credit of each such maker shall be the sole applicable loan limitations."],[1,"(9)(A) Loans and extensions of credit secured by shipping documents or instruments transferring or securing title covering livestock or giving a lien on livestock when the market value of the livestock securing the obligation is not at any time less than 115 per centum of the face amount of the note covered, shall be subject under this section, notwithstanding the collateral requirements set forth in subsection (a)(2), to a maximum limitation equal to 25 per centum of such capital and surplus."],[1,"(B) Loans and extensions of credit which arise from the discount by dealers in dairy cattle of paper given in payment for dairy cattle, which paper carries a full recourse endorsement or unconditional guarantee of the seller, and which are secured by the cattle being sold, shall be subject under this section, notwithstanding the collateral requirements set forth in subsection (a)(2), to a limitation of 25 per centum of such capital and surplus."],[1,"(10) Loans or extensions of credit to the Student Loan Marketing Association shall not be subject to any limitation based on capital and surplus."],[0,"(d) Authority of Comptroller of the Currency"],[0,"(1) The Comptroller of the Currency may prescribe rules and regulations to administer and carry out the purposes of this section, including rules or regulations to define or further define terms used in this section and to establish limits or requirements other than those specified in this section for particular classes or categories of loans or extensions of credit."],[0,"(2) The Comptroller of the Currency also shall have authority to determine when a loan putatively made to a person shall for purposes of this section be attributed to another person."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/84?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§84. Lending limits","tname":"Banks and Banking","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 79","url":"https://www.law.cornell.edu/uscode/text/15/79","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 79a","url":"https://www.law.cornell.edu/uscode/text/15/79a","subs":["(b)"],"stext":{"head":"§79a. Necessity for control of holding companies","paras":[[0,"(a) Interstate nature of holding companies"],[0,"Public-utility holding companies and their subsidiary companies are affected with a national public interest in that, among other things, (1) their securities are widely marketed and distributed by means of the mails and instrumentalities of interstate commerce and are sold to a large number of investors in different States; (2) their service, sales, construction, and other contracts and arrangements are often made and performed by means of the mails and instrumentalities of interstate commerce; (3) their subsidiary public-utility companies often sell and transport gas and electric energy by the use of means and instrumentalities of interstate commerce; (4) their practices in respect of and control over subsidiary companies often materially affect the interstate commerce in which those companies engage; (5) their activities extending over many States are not susceptible of effective control by any State and make difficult, if not impossible, effective State regulation of public-utility companies."],[0,"(b) Protection of investors and interests of consumers"],[0,"Upon the basis of facts disclosed by the reports of the Federal Trade Commission made pursuant to S. Res. 83 (Seventieth Congress, first session), the reports of the Committee on Interstate and Foreign Commerce, House of Representatives, made pursuant to H. Res. 59 (Seventy-second Congress, first session) and H. J. Res. 572 (Seventy-second Congress, second session) and otherwise disclosed and ascertained, it is declared that the national public interest, the interest of investors in the securities of holding companies and their subsidiary companies and affiliates, and the interest of consumers of electric energy and natural and manufactured gas, are or may be adversely affected—"],[1,"(1) when such investors cannot obtain the information necessary to appraise the financial position or earning power of the issuers, because of the absence of uniform standard accounts; when such securities are issued without the approval or consent of the States having jurisdiction over subsidiary public-utility companies; when such securities are issued upon the basis of fictitious or unsound asset values having no fair relation to the sums invested in or the earning capacity of the properties and upon the basis of paper profits from intercompany transactions, or in anticipation of excessive revenues from subsidiary public-utility companies; when such securities are issued by a subsidiary public-utility company under circumstances which subject such company to the burden of supporting an overcapitalized structure and tend to prevent voluntary rate reductions;"],[1,"(2) when subsidiary public-utility companies are subjected to excessive charges for services, construction work, equipment, and materials, or enter into transactions in which evils result from an absence of arm's-length bargaining or from restraint of free and independent competition; when service, management, construction, and other contracts involve the allocation of charges among subsidiary public-utility companies in different States so as to present problems of regulation which cannot be dealt with effectively by the States;"],[1,"(3) when control of subsidiary public-utility companies affects the accounting practices and rate, dividend, and other policies of such companies so as to complicate and obstruct State regulation of such companies, or when control of such companies is exerted through disproportionately small investment;"],[1,"(4) when the growth and extension of holding companies bears no relation to economy of management and operation or the integration and coordination of related operating properties; or"],[1,"(5) when in any other respect there is lack of economy of management and operation of public-utility companies or lack of efficiency and adequacy of service rendered by such companies, or lack of effective public regulation, or lack of economies in the raising of capital."],[0,"(c) Declaration of policy of chapter"],[0,"When abuses of the character above enumerated become persistent and wide-spread the holding company becomes an agency which, unless regulated, is injurious to investors, consumers, and the general public; and it is declared to be the policy of this chapter, in accordance with which policy all the provisions of this chapter shall be interpreted, to meet the problems and eliminate the evils as enumerated in this section, connected with public-utility holding companies which are engaged in interstate commerce or in activities which directly affect or burden interstate commerce; and for the purpose of effectuating such policy to compel the simplification of public-utility holding-company systems and the elimination therefrom of properties detrimental to the proper functioning of such systems, and to provide as soon as practicable for the elimination of public-utility holding companies except as otherwise expressly provided in this chapter."]],"more":false,"ed":"2004","src":"https://www.govinfo.gov/link/uscode/15/79a?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§79a. Necessity for control of holding companies","tname":"Commerce and Trade","by":{"0":""}},{"t":"usc","label":"15 U.S.C. § 77l","url":"https://www.law.cornell.edu/uscode/text/15/77l","subs":["(1)"],"by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 1904","url":"https://www.law.cornell.edu/uscode/text/12/1904","by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 325","url":"https://www.law.cornell.edu/uscode/text/12/325","by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 263","url":"https://www.law.cornell.edu/uscode/text/12/263","by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 343","url":"https://www.law.cornell.edu/uscode/text/12/343","by":{"0":""}}]};